INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-anlagen-betriebe-genehmigungsfrei-gewerbeordnung-bundesrat','PV-Anlagen für Betriebe: Solar und Ladestationen ohne Genehmigung','Gewerbebetriebe dürfen Photovoltaikanlagen, Batteriespeicher und E-Ladestationen künftig unter Auflagen ohne eigenes Genehmigungsverfahren errichten. Der Bundesrat stimmte einstimmig zu.','PV-Anlagen für Betriebe werden in Österreich deutlich einfacher: Nach dem Nationalrat hat am 22. Oktober auch der Bundesrat einstimmig grünes Licht für eine Novelle der Gewerbeordnung gegeben. Gewerbebetriebe sollen Photovoltaikanlagen, E-Ladestationen und Batteriespeicher künftig unter bestimmten Auflagen ohne eigenes gewerberechtliches Genehmigungsverfahren errichten können.

Für viele Unternehmen bedeutete eine Solaranlage am Firmendach bisher, dass die Betriebsanlagengenehmigung angepasst werden musste. Je nach Bundesland wurde das unterschiedlich gehandhabt. Mit der Reform wird die Ausnahme erstmals direkt im Gesetz verankert.

## PV-Anlagen für Betriebe: Was sich konkret ändert

Laut Parlamentskorrespondenz entfällt für Photovoltaikanlagen und Ladestationen für Elektroautos in Gewerbebetrieben das bisherige Genehmigungsverfahren. Im Wirtschaftsausschuss wurden dafür Bedingungen genannt:

- Planung und Errichtung müssen durch einen Baumeister oder einen befugten Elektrotechniker erfolgen.
- Ein Elektrobefund ist alle fünf Jahre vorzulegen, bei außergewöhnlicher Beanspruchung alle drei Jahre.
- Prüfberichte müssen nicht mehr in Papierform im Betrieb aufliegen, sondern können auf Anfrage digital oder schriftlich übermittelt werden.

Ursprünglich waren Stromspeicher im Entwurf nicht ausdrücklich erwähnt. Im Plenum des Nationalrats am 14. Oktober brachten ÖVP, SPÖ, NEOS und Grüne einen gemeinsamen Abänderungsantrag ein. Damit fallen nicht nur Batteriespeicher als Teil einer PV-Anlage unter die Erleichterung, sondern auch Speicher, die für sich allein errichtet werden.

## Branche sieht mehr Rechtssicherheit

Der Bundesverband Photovoltaic Austria (PV&B) begrüßte den Beschluss. Geschäftsführerin Vera Immitzer verwies darauf, dass die Branche seit Jahren eine klare gesetzliche Regelung gefordert habe. Ein Erlass aus dem Jahr 2021 habe zwar bereits Ausnahmen vorgesehen, sei aber nicht in allen Bundesländern einheitlich angewendet worden. Für Betriebe, die Strom vom eigenen Dach nutzen oder Ladepunkte für Kunden und Mitarbeiter anbieten wollen, dürfte damit ein wesentlicher Unsicherheitsfaktor wegfallen.

## Weitere Erleichterungen in der Gewerbeordnung

Die Novelle umfasst neben dem Energiebereich mehrere Punkte, die den Betriebsalltag entlasten sollen:

- **Außengeräte:** Betriebe ohne Betriebsanlagengenehmigung dürfen unter Bedingungen außenliegende Teile von Klimageräten, Lüftungen, Heizungen oder Wärmepumpen montieren. Die Behörde prüft dann nur, ob die Lärmbelastung zumutbar ist, nicht die gesamte Anlage.
- **Längere Fristen:** Die Übergangsfrist für Auflagen steigt von drei auf fünf Jahre. Eine nicht genutzte Betriebsanlagengenehmigung bleibt sieben statt fünf Jahre gültig und kann auf bis zu zehn Jahre verlängert werden. Das soll die Nachnutzung leerstehender Geschäftslokale erleichtern.
- **Betriebsübergaben:** Für Übergaben sind Vereinfachungen vorgesehen.
- **Altersnachweis:** An Automaten und Selbstbedienungskassen kann das Alter künftig mit der ID Austria nachgewiesen werden.
- **Almen:** Almwirtschaften dürfen offene Getränke ausschenken, die Flaschenpflicht fällt.

Laut NEOS sollen durch das Paket mehr als 5.000 Kontrollen vor Ort wegfallen. Ein konkretes Datum für das Inkrafttreten wurde in den Parlamentsmitteilungen nicht genannt; es hängt von der Kundmachung im Bundesgesetzblatt ab.

## Was Unternehmen jetzt beachten sollten

Wer eine PV-Anlage oder Ladestationen am Betriebsstandort plant, sollte vorab klären, ob der eigene Betrieb unter die neuen Bedingungen fällt. Bauordnung, Netzanschluss beim Netzbetreiber und Förderungen sind von der Gewerbeordnung unabhängig und bleiben weiterhin zu beachten. Eine fachkundige Planung durch einen befugten Elektrotechniker ist nach den neuen Regeln ohnehin Voraussetzung.','energie','Photovoltaik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pv-anlagen-betriebe-genehmigungsfrei-gewerbeordnung-bundesrat.webp','Parlamentskorrespondenz (Bundesrat, 22.10.2026)','https://www.ots.at/presseaussendung/OTS_20261022_OTS0207/bundesrat-breite-zustimmung-zu-regelungen-fuer-versorgungssicherheit-bei-energie-wirtschafts-und-bedarfsguetern','published','2026-10-25T14:50:00.000Z','2026-10-25T14:46:16.904Z','PV-Anlagen für Betriebe: künftig genehmigungsfrei','PV-Anlagen für Betriebe: Der Bundesrat hat die Gewerbeordnung reformiert. Solar, Speicher und Ladestationen ohne Genehmigung – die Bedingungen.','PV-Anlagen für Betriebe','["PV-Anlagen für Betriebe","Gewerbeordnung Novelle 2026","Photovoltaik Gewerbe Genehmigung","Betriebsanlagengenehmigung PV","E-Ladestation Betrieb genehmigungsfrei","Batteriespeicher Gewerbe","Bundesrat Gewerbeordnung","PV Firmendach Österreich"]','PV-Anlagen für Betriebe: Solarmodule auf dem Dach eines Gewerbebetriebs mit E-Ladestation','Flat roof of a small Austrian craft workshop building with rows of solar panels and a wall-mounted electric vehicle charging station next to a parked electric van in the courtyard, rolling hills of Lower Austria in the background, autumn afternoon, no text, no logos, no readable signs','[{"q":"Brauchen Betriebe für eine PV-Anlage noch eine gewerberechtliche Genehmigung?","a":"Nach der Novelle nicht mehr, wenn die Bedingungen erfüllt sind – etwa Planung und Errichtung durch Baumeister oder Elektrotechniker und regelmäßige Elektrobefunde."},{"q":"Gilt die Erleichterung auch für Batteriespeicher?","a":"Ja. Durch einen Abänderungsantrag im Nationalrat sind auch Speicher erfasst, die ohne PV-Anlage errichtet werden."},{"q":"Ab wann gelten die neuen Regeln?","a":"Ein Datum wurde nicht genannt; die Novelle tritt nach der Kundmachung im Bundesgesetzblatt in Kraft."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
